def half_endo(summands):
    def _eval(P):
        E = P.curve()
        assert P in E
        F = E.base_field()
        if (halves := P.division_points(_sage_const_2 )):
            Q = halves[_sage_const_0 ]
        else:
            Q = E.change_ring(F.extension(_sage_const_2 ,'v'))(P)
        R = sum(endo._eval(Q) for endo in summands)
        return E(R)
    return _eval

