def dlp(P, Q, R):
    n = P.order()
    assert(n != _sage_const_0 )
    assert P.order() == Q.order()
    assert (order_from_multiple(R, p**_sage_const_2 -_sage_const_1 , plist)).divides(P.order())
    e = Fp2(P.weil_pairing(Q, n))
    a = Fp2(R.weil_pairing(Q, n))
    a = discrete_log(a,e,n)
    b = Fp2(P.weil_pairing(R, n))
    b = discrete_log(b,e,n)
    assert a*P + b*Q == R
    return a, b

def matrix_of_isogeny(phi):
    imP, imQ = map(phi, (P,Q))
    vecP = dlp(P, Q, imP)
    vecQ = dlp(P, Q, imQ)
    mat = matrix(Zmod(T<<f), [vecP, vecQ]).transpose()
    assert imP == ZZ(mat[_sage_const_0 ][_sage_const_0 ])*P + ZZ(mat[_sage_const_1 ][_sage_const_0 ])*Q
    assert imQ == ZZ(mat[_sage_const_0 ][_sage_const_1 ])*P + ZZ(mat[_sage_const_1 ][_sage_const_1 ])*Q
    return mat

