def field2limbs(el):
    l = _sage_const_1  + floor(log(p, _sage_const_2 **_sage_const_64 ))
    el = Fp2(el)
    vs = [[(int(c) >> _sage_const_64 *i) % _sage_const_2 **_sage_const_64  for i in range(l)] for c in el]
    return vs

def fmt_basis(name, P, Q):
    vs = [
            [field2limbs(T[_sage_const_0 ]), field2limbs(T[_sage_const_2 ])]
            for T in (P,Q,P-Q)
        ]
    return Object('ec_basis_t', name, vs)

